#!/bin/bash
# Deploy script for lee.app.nz
# Auto-generated by setup_cloudflare_static_site.py

# Colors for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
NC='\033[0m' # No Color

echo -e "${GREEN}🚀 Deploying to lee.app.nz${NC}"

# Check if required environment variables are set
if [ -z "$R2_ACCESS_KEY_ID" ] || [ -z "$R2_SECRET_ACCESS_KEY" ]; then
    echo -e "${RED}❌ Error: R2_ACCESS_KEY_ID and R2_SECRET_ACCESS_KEY environment variables must be set${NC}"
    exit 1
fi

# Build the site first
echo -e "${YELLOW}Building site...${NC}"
if [ -f "./build.sh" ]; then
    ./build.sh
    if [ $? -ne 0 ]; then
        echo -e "${RED}❌ Build failed${NC}"
        exit 1
    fi
else
    echo -e "${RED}❌ Error: build.sh not found${NC}"
    exit 1
fi

# Change to build directory for deployment
cd build || exit 1

# Get account ID (you may want to hardcode this after first run)
ACCOUNT_ID="f76d25b8b86cfa5638f43016510d8f77"

# Sync using rclone (preferred method)
if command -v rclone &> /dev/null; then
    echo -e "${YELLOW}Using rclone to sync files...${NC}"
    
    # Configure rclone if not already configured
    if ! rclone listremotes | grep -q "r2:"; then
        echo "Configuring rclone for R2..."
        rclone config create r2 s3 \
            provider=Cloudflare \
            access_key_id=$R2_ACCESS_KEY_ID \
            secret_access_key=$R2_SECRET_ACCESS_KEY \
            endpoint=https://$ACCOUNT_ID.r2.cloudflarestorage.com \
            acl=private
    fi
    
    # Sync files
    rclone sync . r2:lee-app-nz/ \
        --exclude .git/ \
        --exclude node_modules/ \
        --exclude .env \
        --exclude "*.pyc" \
        --exclude __pycache__/ \
        --exclude .DS_Store \
        --progress
        
# Use AWS CLI as fallback
elif command -v aws &> /dev/null; then
    echo -e "${YELLOW}Using AWS CLI to sync files...${NC}"
    
    export AWS_ACCESS_KEY_ID=$R2_ACCESS_KEY_ID
    export AWS_SECRET_ACCESS_KEY=$R2_SECRET_ACCESS_KEY
    
    aws s3 sync . s3://lee-app-nz/ \
        --endpoint-url https://$ACCOUNT_ID.r2.cloudflarestorage.com \
        --exclude ".git/*" \
        --exclude "node_modules/*" \
        --exclude ".env" \
        --exclude "*.pyc" \
        --exclude "__pycache__/*" \
        --exclude ".DS_Store" \
        --delete
else
    echo -e "${RED}❌ Error: Neither rclone nor aws-cli found${NC}"
    echo "Install one of them:"
    echo "  rclone: https://rclone.org/install/"
    echo "  aws-cli: pip install awscli"
    exit 1
fi

echo -e "${GREEN}✅ Deployment complete!${NC}"
echo -e "View your site at: ${GREEN}https://lee.app.nz${NC}"

# Return to original directory
cd ..
